import data from "@/data/galleries.json";

// Gallery types plus the file-based content generated by
// scripts/prepare-galleries.mjs. The live, dashboard-editable versions are
// read through src/lib/data/galleries.ts; these files are the fallback and
// the seed for the database.

export interface Photo {
  src: string;
  w: number;
  h: number;
  caption?: string;
}

export interface LukaChild {
  slug: string;
  /** Display name (the prayer card itself shows the name in Amharic). */
  name: string;
  portrait: Photo;
  /** The full prayer card; falls back to the portrait when none was uploaded. */
  card: Photo;
  /** How many times visitors committed to pray for this child. */
  prayers?: number;
}

export interface Album {
  id: string;
  icon: string;
  title: string;
  tag: string;
  descr: string;
  photos: Photo[];
}

const manifest = data as { luka: LukaChild[]; albums: Record<string, Photo[]> };

export const FILE_CHILDREN: LukaChild[] = manifest.luka;
export const FILE_ALBUMS: Record<string, Photo[]> = manifest.albums;
export const FILE_ALBUM_ICONS: Record<string, string> = { carnival: "sparkles", vision: "church" };
